WITH base AS (SELECT * FROM subscriptions WHERE monthly_fee >= 160 AND end_date < '2024-12-01'), summary AS (SELECT customer_id, CASE WHEN YEAR(end_date) < 2024 THEN 'before_2024' WHEN YEAR(end_date) = 2024 THEN '2024' ELSE 'after_2024' END AS end_cohort, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list FROM base GROUP BY customer_id, CASE WHEN YEAR(end_date) < 2024 THEN 'before_2024' WHEN YEAR(end_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT customer_id, end_cohort, plan_list FROM summary ORDER BY 2;
